  "shell.lane.slotKeyRefused.message": "PTT 被拒——發射停止",
  "shell.lane.slotKeyRefused.detail": "電臺在 {{time}} UTC 未接受 PTT（{{why}}），因此該次通聯未發出且發射已關閉。請檢查你的 PTT 方式與 CAT/連線埠，然後重新開啟發射。",
  "shell.lane.slotKeyRefused.flex.notYetDax": "Nexus 未在 {{time}} UTC 鍵控 {{mode}} 通聯：Flex 原生 DAX 音訊已開啟，但電臺尚未從其經 DAX 接收來自 Nexus 的發射音訊。未發出任何內容，發射已關閉。Nexus 會在片刻內完成電臺設定；隨後請重新開啟發射。",
  "shell.lane.slotKeyRefused.flex.daxUnfed": "Nexus 未在 {{time}} UTC 鍵控 {{mode}} 通聯：Flex 原生 DAX 音訊已關閉，但電臺仍按 Nexus 所設從其經 DAX 接收發射音訊，而此刻 DAX 無輸入。未發出任何內容，發射已關閉。Nexus 會在片刻內將電臺切回麥克風輸入；隨後請重新開啟發射。",
  "shell.lane.slotKeyRefused.txAudio": "Nexus 未在 {{time}} UTC 鍵控電臺，因為發射音訊輸出無法開啟（{{why}}）。未發出任何內容，發射已關閉。請檢查設定中的輸出裝置（TX）（可能有其他程式佔用，或裝置已拔出），然後重新開啟發射。",
  "shell.lane.slotUnkeyFailed.message": "PTT 關閉失敗——發射停止",
  "shell.lane.slotUnkeyFailed.detail": "電臺在 {{time}} UTC 未接受 PTT 關閉（{{why}}），因此發射已關閉。它可能仍在發射：請立即檢查電臺。Nexus 會持續傳送 PTT 關閉指令，直到電臺接受。待電臺恢復接收後再重新開啟發射。",
  "shell.lane.slotAudioLost.message": "通聯結束——發射停止",
  "shell.lane.slotAudioLost.detail": "承載某次通聯音訊至電臺的路由（Flex DAX 或 TCI）在該次通聯中途於 {{time}} UTC 中斷，因此其餘部分會靜默發出。Nexus 就此結束該次通聯並關閉發射。請重新開啟發射以繼續。",
  "shell.lane.slotOverDropped.message": "通聯丟棄——電臺鍵控過晚",
  "shell.lane.slotOverDropped.detail": "此次通聯被丟棄：電臺僅在 {{time}} UTC 鍵控，即你的時隙結束後 {{late}}（CAT 較慢），因此 Nexus 立即解除鍵控且未傳送任何內容，並保持發射開啟以等待你的下一次通聯。分頻操作會在每次鍵控前向電臺傳送指令，在慢速 CAT 鏈路上可能耗時數秒：若此情況持續，請檢查設定中的 CAT 鏈路與分頻操作。",
  "shell.lane.pttRefused.message": "PTT 被拒",
  "shell.lane.pttRefused.detail": "Nexus 未在 {{time}} UTC 鍵控 {{mode}} 通聯：電臺仍按 Nexus 所設從其經 DAX 接收發射音訊，而非來自麥克風，因此你的語音不會發出。未傳送任何內容。鬆開 PTT，Nexus 會在片刻內將電臺切回麥克風輸入；隨後再次按下 PTT。",
  "shell.lane.voiceDropped.message": "語音訊息已丟棄",
  "shell.lane.voiceDropped.noDax": "Nexus 未在 {{time}} UTC 播放語音訊息：電臺未在 2 秒內將其發射音訊切換至 DAX，因此未鍵控任何內容。該訊息被丟棄而非暫存；請再次按下其按鍵。",
  "shell.lane.voiceDropped.keyed": "Nexus 未在 {{time}} UTC 播放語音訊息：另有程式正在發射或已先行鍵控電臺（你的麥克風或 PTT、一個調諧載波、另一程式），因此未鍵控任何內容。該訊息被丟棄而非暫存。",
  "shell.lane.clockRepairHold.message": "時鐘修復——發射掛起",
  "shell.lane.clockRepairHold.detail": "Nexus 正在修復本機時鐘。在修復完成前（最多兩分鐘）不會開始發射，以免時鐘在通聯中途移動。",
  "shell.lane.txOnHeld.message": "發射掛起——需要批准",
