  "assist.state.unassisted": "非輔助",
  "assist.state.assisted": "輔助",
  "assist.sources.off": "輔助來源關閉：CW 譯碼器、DX cluster / RBN、PSK Reporter 缺項、Super Check Partial、呼號歷史。",
  "assist.sources.offSince": "自 {{since}} 起輔助來源關閉：CW 譯碼器、DX cluster / RBN、PSK Reporter 缺項、Super Check Partial、呼號歷史。",
  "assist.sources.on": "CW 譯碼器、DX cluster / RBN、PSK Reporter 缺項、Super Check Partial 與呼號歷史正在提供呼號與交換輔助。",
  "assist.sources.onSince": "自 {{since}} 起，CW 譯碼器、DX cluster / RBN、PSK Reporter 缺項、Super Check Partial 與呼號歷史正在提供呼號與交換輔助。",
  "assist.toggle.declare": "申報非輔助參賽",
  "assist.toggle.end": "結束非輔助參賽",
  "assist.why.summary": "這對你的比賽類別意味著什麼",
  "assist.why.cqww": "<b>CQ WW</b> 規則 VIII.2 將「CW 譯碼器、DX cluster、DX spotting 網站……本地或遠端的呼號與頻率譯碼技術（如 CW Skimmer 或 Reverse Beacon Network）」計為 QSO 尋找輔助。使用其中任何一項都會將參賽歸入<b>單人輔助（Single Operator Assisted，V.A.2）</b>而非單人（V.A.1）。",
  "assist.why.arrl": "<b>ARRL</b> 比賽稱之為 spotting 輔助，並點名「PSKReporter、Telnet、DX spotting 網站或公告板系統、自動化多通道譯碼器」。單人不可使用它（HCAT.1.1：「不允許使用 spotting 輔助。」）。<b>單人無限（Single Operator Unlimited）</b>可以使用（HCAT.2.1）。ARRL 術語表將多通道譯碼器定義為「同時顯示多個已譯碼訊號」的軟體。Nexus 一次只譯碼一個訊號，因此該定義並不描述其 CW 譯碼器。但它確實描述了 cluster、RBN 與 PSK Reporter 饋送。",
  "assist.why.ownDecodes": "你電臺自身的<b>數字譯碼</b>（含 FT8 與 FT4）在非輔助模式下仍持續供給缺項面板。兩套規則都未將它們單獨列出：兩者都將任何能識別呼號或倍乘數的技術計為輔助，因此若你的比賽將它們計入，請勿用缺項面板來尋找電臺。你向外的 PSK Reporter 上傳也持續執行，因為 ARRL 說「為他人站生成 spotting 資訊不被視為 spotting 輔助」。",
  "assist.why.notCovered": "<b>此開關未覆蓋：</b>POTA 與 SOTA activator spots 仍會到達。兩套規則都未點名這些饋送，但都將輔助定義得足夠寬泛以納入它們，因此若你參加的比賽將它們計入，請手動關閉 POTA/SOTA 功能。",
  "assist.why.checkRules": "規則因比賽而異，且年間會變化，因此<b>請查閱你所參加比賽的規則</b>。本說明報告 CQ WW 與 ARRL 目前公佈的規則。它不是類別裁決。",
  "assist.keep": "你自己的設定從不被重寫。結束非輔助模式會完全按你原先的樣子恢復譯碼器與饋送。",
