  "logbook.confirmations.buttonTitle": "從您已設定的 LoTW、eQSL 和 QRZ 下載完整歷史記錄，並列出那些持有某確認或 LoTW 上傳標記的通訊——這些標記本應屬於另一條通訊，或不屬於任何通訊——供您勾選並移除。",
  "logbook.confirmations.title": "檢查確認",
  "logbook.confirmations.intro": "早期版本的 Nexus 可能把來自 LoTW、eQSL 或 QRZ 的某條通訊確認，或者 LoTW 記錄的上傳標記，錯誤地放到同一 UTC 日內、同一電臺、同一頻段和模式的另一條通訊上。檢查功能會從您設定的每個服務一次性下載完整歷史記錄（LoTW 可能需要幾分鐘），並列出每條持有某確認或上傳標記的通訊——這些標記在服務的原始記錄中本應屬於另一條通訊，或不屬於任何通訊。只有當原始記錄判定應勾選時，行才會自動勾選。在您按下按鈕之前，不會發生任何更改，不會上傳任何資料，也不會觸動任何紙質卡片。",
