  "scope.strip.detector.average": "平均",
  "scope.strip.detector.average.title": "平均 — 當一個畫素覆蓋多個頻率分箱時，繪製其平均功率。噪底更平滑；寬檢視中的窄載波讀數更低。",
  "scope.gear.aria": "顯示設定",
