  "scope.rows.smooth.label": "平滑捲動",
  "scope.rows.sweep.label": "每行一次掃描",
  "scope.rows.smooth.title": "平滑捲動 — 瀑布圖以穩定速率移動。當電臺頻譜掃描慢於該速率時，最新掃描會被重複，直到下一條到達，且每次重複記錄為一行。點選切換為每行一次掃描。",
  "scope.rows.sweep.title": "每行一次掃描 — 瀑布圖僅在電臺傳送新掃描時移動，因此慢速頻譜緩慢、分步捲動，且每行都是新的。點選切換為平滑捲動。",
  "scope.hidef.label": "高畫質",
  "scope.fast.label": "快速",
  "scope.hidef.on.title": "高畫質 — CW 通帶單獨分析：穩定載波繪製約 4–5 Hz 寬，相距 10 Hz 的兩個訊號保持分離，鍵控保留其間隔。影像比音訊滯後約四分之一秒。點選切換為快速。",
  "scope.hidef.off.title": "快速 — 頻譜像其他顯示一樣分析：影像緊隨音訊，載波繪製更寬（解析度在 ⚙ 之下）。點選切換為高畫質。",
