  "settings.pounce.note": "當所需電臺出現在叢集或 RBN 上的瞬間即打斷你，而非等待點報板重新整理。無論 Nexus 是否是你正在看的視窗，都會播放響亮提示音，橫幅提供一鍵通聯。預設關閉，需手動開啟。「罕見」有多罕見取決於你自身的統計：若你正在追逐前一百個實體，則幾乎每個 DX 點報都是新目標，此功能會喋喋不休。當你的日誌足夠豐富、新目標確實成為事件時，再從 <em>僅新 DXCC 實體</em> 開始。每個電臺在每個頻段和模式僅提醒一次。",
