  "settings.radios.add.action": "+ 新增電臺",
  "settings.radios.hint.multi": "下方的電臺 / CAT + 音訊設定編輯「{{name}}」。每臺電臺都有自己的 CAT + 音訊 — 點選任意電臺的「編輯」即可配置它，而不會改變你正在操作的電臺；「設為活動」則交換你的操作電臺。以下這些電臺 / CAT 控制是全站的，因此更改一項會影響所有電臺：「介面在 CAT 連線埠觸發 RTS」、「分頻操作」、「跟隨電臺的分頻」、「滾輪調諧靈敏度」，以及在進階下的「共享連線埠」、「序列握手」和「啟動時鍵控線」。",
  "settings.radios.hint.single": "同時執行兩臺電臺 — 例如一臺 HF 電臺加一臺不同天線的 VHF/UHF 電臺？新增第二臺電臺；之後你可編輯其中任意一臺而不打斷正在操作的電臺。新手可忽略此項。",
