  "settings.dataFolder.legend": "資料與日誌資料夾",
  "settings.dataFolder.note": "你的日誌簿、Nexus 下載的資料表以及 Winlink 信箱都位於一個資料夾中。請將其保留在本機的一個驅動器上。Nexus 將你的日誌簿儲存在資料庫中，而網路驅動器上的資料庫可能因跨網路的檔案鎖定方式而損壞，因此網路驅動器被拒絕。同步資料夾（Dropbox、OneDrive、iCloud、Google Drive）是允許的，但一次僅允許一個 Nexus 使用它：兩臺電腦透過同步使用者端寫入同一日誌簿會產生衝突副本，而非合併日誌。",
