  "aprs.health.norf.detail": "此電臺不覆蓋 {{freq}} MHz，因此無法接收射頻 APRS。射頻 APRS 需要 VHF 電臺。沒有它網際網路資料來源也能工作 — 開啟即可檢視其他臺站報告的 APRS 流量。",
  "aprs.health.off.label": "監視已關",
