  "aprs.health.wrongMode.detail": "電臺在 {{want}} 上，但模式是 {{mode}} — APRS 需要 FM。把 FM 分組音訊按 SSB 解調會亂碼，無論訊號多強都解不出來。請調到 APRS 頻道。",
  "aprs.health.wrongFreqMode.detail": "電臺在 {{dial}} {{mode}} — APRS 需要 {{want}} FM。此頻道上任何內容都無法按 APRS 分組解碼，無論音訊電平顯示什麼。請調到 APRS 頻道。",
  "aprs.health.wrongFreq.detail": "電臺在 {{dial}} — APRS 需要 {{want}}。此頻道上任何內容都無法按 APRS 分組解碼，無論音訊電平顯示什麼。請調到 APRS 頻道。",
  "aprs.health.noCapture.label": "無輸入",
  "aprs.health.noCapture.detail": "已啟用，但完全沒有音訊樣本到達 — 採集裝置沒有送出任何資料。請檢查 設定 ▸ 電臺 ▸ 音訊 中的輸入裝置（接收）是否為電臺（而不是麥克風或已斷開的裝置）；揚聲器裡聽到的聲音並不代表應用正在採集的聲音。",
  "aprs.health.decoding.label": "已解碼 {{count}} 個",
  "aprs.health.decoding.detail": "啟用以來已解碼 {{count}} 個分組。即時 {{level}}。",
  "aprs.health.decoding.detail.aged": "啟用以來已解碼 {{count}} 個分組，最近一次在 {{age}}。即時 {{level}}。",
  "aprs.health.unreadable.label": "{{count}} 個 CRC 校驗失敗",
  "aprs.health.unreadable.detail": "啟用以來聽到 {{count}} 個突發，最近一次在 {{age}} — 均未透過校驗。其中一部分屬正常：若靜噪在突發中途開啟，分組開頭會丟失，殘缺的分組永遠無法透過。只有當從未解出任何內容時才算故障 — 那時請檢查電臺是否在 {{channel}} 且為 FM。{{advice}} 最近一次突發峰值為 {{burst}}；即時 {{level}}。",
  "aprs.health.advice.clipping": "該突發正在削波（峰值 {{peak}}，有 {{samples}} 個樣本頂到上限）— 請降低電臺的 USB AF 輸出電平，或降低該裝置在 Windows 中的輸入電平。分組能承受相當程度的削波，因此這損失的是餘量而非解位元速率，但也沒必要頂到上限。",
  "aprs.health.advice.quiet": "該突發峰值為 {{peak}}，遠低於健康區間 {{min}} 至 {{max}} — 請提高電臺的 USB AF 輸出電平（IC-9700：SET > Connectors > USB AF Output Level）或該裝置在 Windows 中的輸入電平。這能留出抗噪餘量；但它本身並不是校驗失敗的原因。",
  "aprs.health.silent.label": "靜音",
