  "js8.dock.hbNet.title.speed": "在 {{speed}} 速率下不傳送心跳：JS8Call 僅在 Slow、Normal 和 Fast 下傳送心跳及其確認。在你更改速率之前 HB 會隱藏，而此開關會保留其設定。",
  "js8.dock.hbAck.suppressed.speed": "心跳確認已開啟，但在 {{speed}} 速率下不會發出：JS8Call 僅在 Slow、Normal 和 Fast 下應答心跳。",
  "js8.dock.hbAck.suppressed.arriving": "心跳確認已開啟，但目前被暫緩：仍有訊息正在接收，與 JS8Call 一致。",
  "js8.dock.hbAck.suppressed.qsoPause": "心跳確認已開啟，但目前被暫緩：收件框中存在呼號（QSO 暫停，設定 ▸ 數字 ▸ JS8）。清空收件框即可重新應答心跳。",
  "js8.dock.hbAck.rateBlocked": "正在忽略以下臺站的心跳，因為它們的心跳間隔短於 55 分鐘：{{calls}}。",
  "js8.toast.hb.failed": "心跳未傳送",
  "js8.dock.cmd.aria": "定向命令",
  "js8.dock.cmd.none": "訊息（無命令）",
  "js8.dock.cmd.freetext": "自由文字",
  "js8.dock.estimate": "≈ {{count}} 幀 · ≈ {{secs}} 秒",
  "js8.dock.estimate.over": "≈ {{count}} 幀 — 超過 {{max}} 幀的發射時長上限；請縮短",
  "js8.dock.estimate.title": "這需要佔用多少週期的空口時間（每週期一幀）。僅為估算 — 引擎會實際打包，並拒絕任何超過十分鐘空口時長的內容。",
  "js8.dock.autoreply.title.off": "自動回覆已關閉 — 發給你的 SNR?、GRID?、INFO? 或 STATUS? 的答覆，以及對 MSG 或中繼的 ACK，會放入訊息框由你自行傳送，與 JS8Call 一致，絕不自行發射；QUERY MSGS 不會得到應答。點選開啟（會被記住）。僅在發射開啟時才會應答。",
  "js8.dock.autoreply.title.on": "自動回覆已開啟，但發射已關閉 — 不會發射；回覆會顯示為「本應回覆」。啟用發射（頂欄膠囊）後回覆才會發出。",
  "js8.dock.autoreply.title.armed": "自動回覆已就緒：發給你的、或發給你加入的組的 SNR?、GRID?、INFO?、QUERY 和 MSG 都會得到應答，若設定在詢問時要求確認，則在你說「是」之後回覆。點選關閉。",
  "js8.dock.relay.title.off": "中繼已關閉 — 經你轉發的 > 訊息只顯示，不再傳遞。點選開啟（會被記住）。中繼屬於第三方資訊，你需對其負責。",
  "js8.dock.relay.title.on": "中繼已開啟，但發射已關閉 — 不會發射。啟用發射（頂欄膠囊）後方可中繼。",
  "js8.dock.relay.title.armed": "中繼已就緒：經你轉發的 > 訊息會以 *DE* 你的呼號 重新傳送，最後一跳會被確認。若自動回覆關閉，則改為放入訊息框由你傳送。點選關閉。",
  "js8.dock.relay.notArmed.needsAuto": "中繼已開啟，但自動回覆關閉時，轉發的訊息會放入訊息框由你傳送，絕不自行發射。開啟自動回覆才能在空口上中繼。",
  "js8.dock.hbAck.title.off": "心跳確認已關閉（JS8Call 的預設設定）。點選可用 HEARTBEAT SNR 應答心跳（會被記住）。僅在發射開啟時才會應答。",
  "js8.dock.hbAck.title.on": "心跳確認已開啟，但發射已關閉 — 不會發射。請啟用發射（頂欄膠囊）。",
  "js8.dock.hbAck.title.armed": "心跳確認已就緒：每聽到一次心跳，就在隨機空閒時隙用 HEARTBEAT SNR 應答。點選關閉。",
  "js8.dock.hbAck.notArmed.needsHb": "心跳確認已開啟，但與 JS8Call 一致，只有在心跳組網（HB NET）開啟時才會應答。HB NET 本身不傳送任何內容。",
  "js8.dock.hbAck.notArmed.needsAuto": "心跳確認已開啟，但與 JS8Call 一致，只有在自動回覆開啟時才會應答。請開啟自動回覆。",
  "js8.dock.hbAck.notArmed.needsHbAndAuto": "心跳確認已開啟，但與 JS8Call 一致，只有心跳組網（HB NET）和自動回覆同時開啟時才會應答。HB NET 本身不傳送任何內容。",
  "js8.dock.arm.differs": "JS8Call 一步完成的事，這裡分兩步：該開關是第二步，頂欄的發射膠囊是第一步，只有兩者都開啟時才會顯示「已就緒」。",
  "js8.dock.notArmed.idle": "未就緒：你已 {{min}} 分鐘無操作，空閒看門狗將其掛起。下一次傳送、切換開關、更改速率，或在收件箱中讀取/刪除，都會恢復它。",
  "js8.dock.pending.txOff": "本應回覆 {{to}} — 但發射已關閉，不會發射：{{text}}",
  "js8.toast.idleTripped": "JS8 空閒看門狗：操作員已 {{min}} 分鐘無操作 — HB、AUTOREPLY、RELAY、HB ACK 和迴圈 CQ 均已關閉。發射狀態保持你離開時的樣子。下一次傳送、切換開關、更改速率，或在收件箱中讀取/刪除，會按設定恢復 AUTOREPLY、RELAY 和 HB ACK；HB 和迴圈 CQ 需你手動開啟。",
