  "phone.txContract.freq.title": "你下一次發段實際發射的頻率 — 由引擎自身給出，已計入確認的異頻和 XIT 偏移。異頻狀態下，這並非你的接收頻率。",
  "phone.txContract.freq.commanded.title": "Nexus 根據其下發的指令推算出該頻率，無法全部與電臺核對 — 或者沒有 CAT 鏈路，或者啟用了 XIT 且 clarifier 只寫不讀，因此在電臺上擰出的偏移不會顯示在這裡。",
  "phone.txContract.noEmission.title": "該臺站未報告發射頻率。Nexus 不會用你的接收頻率頂替 — 異頻狀態下二者是無關的數字。",
  "phone.txContract.repeaterShift.title": "在 FM 中繼場景下，Nexus 無法給出你的發射頻率 — 頻移由電臺施加，不在引擎報告的頻率中，因此在此列印只會是貼著發射標籤的接收頻率。請在 設定 ▸ 電臺 中核對頻移，或直接在電臺上檢視。",
  "phone.txContract.mode.title": "你下一次發段所用的模式，以及 Nexus 的來源。這與日誌寫入的是同一次回讀，因此此處所見與記錄內容不會矛盾。",
  "phone.txContract.split.title": "你的發射頻率相對接收頻率的偏移（kHz）",
  "phone.txContract.split.commanded.title": "Nexus 向電臺請求了該異頻。快照不包含電臺自身的確認，因此這裡顯示的是下發值而非回讀值 — 若堆積中對方聽不到你，請在電臺上核對。",
  "phone.txContract.xit.title": "發射微調 — 疊加到發射頻率上的偏移（Hz）",
  "phone.txContract.xit.commanded.title": "Nexus 無法從任何電臺讀回 XIT，因此這裡顯示的是 Nexus 下發的值 — 未必是發射機的實際位置。在電臺自身 clarifier 旋鈕上設定的偏移不會出現在這裡。",
  "phone.txContract.power.title": "你的功率設定，以及電臺最近一次實際測得的輸出。無標記時：若 CAT 有回報則為電臺回讀值，否則為最後一次下發值，且無法區分是哪種。",
