  "phone.mic.title": "話筒增益 — 提高到 SSB 峰值剛觸及 ALC 區間",
  "phone.analog.af.aria": "音訊增益",
  "phone.analog.af.title": "音訊增益 — 電臺自身音量。若你的音效卡取自電臺揚聲器或耳機口，它也會決定解碼器聽到的電平，因此把它調到很低會同時停掉 FT8、RTTY、PSK 和揚聲器輸出。自帶 USB 音訊、或使用固定電平 ACC/DATA 介面的電臺不受影響。",
  "phone.analog.af.mutesDecode.label": "解碼？",
  "phone.analog.af.mutesDecode.title": "音訊增益幾乎調到最低。若解碼器透過電臺揚聲器或耳機口收聽，它也已靜音。請提高音訊增益，或改用 USB 編解碼器或後部 ACC/DATA 介面供音效卡，這些不受此控制元件影響。",
  "phone.analog.rf.aria": "射頻增益",
  "phone.analog.rf.title": "射頻增益 — 控制接收前端，不是發射功率。在強訊號波段上把它調低，可把訊號從 AGC 正在壓著的雜訊中提出來。",
  "phone.analog.sql.aria": "靜噪",
  "phone.analog.sql.title": "靜噪 — 訊號需達到的電平門檻。FM 下正常使用；在 SSB、CW 和資料模式下請完全開啟，因為多數電臺（包括 USB 音訊通路）靜噪關閉時會同時靜音解碼器所聽的音訊。",
  "phone.analog.sql.mutesDecode.label": "解碼？",
  "phone.analog.sql.mutesDecode.title": "在 FM 之外的模式下靜噪仍開著。多數電臺此時會連同解碼器所聽的音訊一起靜音，因此在有訊號打破靜噪之前什麼都解不出來。SSB、CW 和資料模式下請把它完全關到底。",
  "phone.filter.title": "接收濾波器 / 通頻寬度（CAT）",
