  "remote.approve": "批准",
  "remote.approval.title": "允許 {{browser}} 串流該臺站？",
  "remote.approval.body": "一個登入了你遠端賬戶的瀏覽器請求串流該臺站，並像你在此一樣操作它，包括發射。僅當該金鑰與瀏覽器顯示的金鑰一致時才批准：{{key}}。",
  "remote.approval.bodyAgain": "此瀏覽器此前已獲批准，但需在此重新批准後才能串流。串流時它可像你在此一樣操作該臺站，包括發射。僅當該金鑰與瀏覽器顯示的金鑰一致時才批准：{{key}}。",
  "remote.approval.computerTitle": "允許 {{computer}} 操作該臺站？",
  "remote.approval.computerBody": "{{platform}} 上登入了你遠端賬戶的 Nexus 請求透過網際網路像你在此一樣操作該臺站，包括發射。僅當該金鑰與那臺電腦上 Nexus 顯示的金鑰一致時才批准：{{key}}。",
  "remote.approval.computerBodyAgain": "{{platform}} 上的 Nexus 此前已獲批准，但需在此重新批准後才能連線。連線後它可像你在此一樣操作該臺站，包括發射。僅當該金鑰與那臺電腦上 Nexus 顯示的金鑰一致時才批准：{{key}}。",
  "remote.approval.deny": "拒絕",
  "remote.approval.heldTitle": "允許 {{device}} 發射？",
  "remote.approval.heldBody": "一個登入了你遠端賬戶的瀏覽器。它現在可以收聽和調諧，發射則等待你的許可。僅當該金鑰與瀏覽器顯示的金鑰一致時才允許：{{key}}。",
  "remote.approval.heldComputerBody": "{{platform}} 上登入了你遠端賬戶的 Nexus。它現在可以收聽和調諧，發射則等待你的許可。僅當該金鑰與那臺電腦上 Nexus 顯示的金鑰一致時才允許：{{key}}。",
  "remote.approval.notNow": "稍後",
  "remote.lan.switch": "經此網路使用遠端",
  "remote.lan.intro": "允許此網路上的另一臺電腦上的 Nexus 操作該臺站，無需網際網路。每臺電腦在此配對一次；在你移除之前會一直保持訪問權。",
