  "remote.lan.guest": "訪客網路或隔離裝置的網路會阻止其他電腦訪問本機，而 Nexus 在此無法判斷這種情況。",
  "remote.lan.firewall.ask": "當 Windows 詢問 Nexus 是否可以使用此網路時，請僅允許「專用網路」。",
  "remote.lan.firewall.public": "Windows 將此網路標記為「公用」，因此其防火牆會阻止其他電腦訪問。若這是你自己的網路，請在 Windows 設定 ▸ 網路和 Internet 中改為「專用」。",
  "remote.lan.firewall.blocked": "Windows 防火牆在此網路上阻止了 Nexus，取消其詢問後即會如此。請在 Windows 安全中心 ▸ 防火牆和網路保護 ▸ 允許應用透過防火牆 中允許 Nexus 使用專用網路。",
  "remote.lan.firewall.blocksAll": "Windows 防火牆阻止了此網路上的所有入站連線，因此任何其他電腦都無法訪問該臺站。",
  "remote.lan.firewall.managed": "此電腦的防火牆由管理員策略設定，可能會阻止其他電腦訪問。請讓管理者允許 Nexus。",
  "remote.lan.firewall.silent": "Windows 防火牆在此網路上會不經詢問地阻止新程式。請在 Windows 安全中心 ▸ 防火牆和網路保護 ▸ 允許應用透過防火牆 中允許 Nexus 使用專用網路。",
  "remote.lan.reach.otherNetwork": "該地址不在此電腦的網路上。請接入臺站所在的網路，或核對臺站顯示的地址。",
  "remote.lan.reach.refused": "臺站電腦有響應，但該連線埠沒有程式監聽：那裡的「經此網路使用遠端」已關閉，或使用了其他連線埠。請核對臺站顯示的地址。",
  "remote.lan.reach.noAnswer": "臺站沒有回應。那裡的「經此網路使用遠端」可能已關閉、其防火牆可能阻止了 Nexus（請在臺站允許其使用專用網路）、網路可能隔離了裝置（訪客 Wi-Fi 常常如此），或者臺站處於休眠。Nexus 在此無法判斷是哪一種。",
