  "settings.contestPick.entryAxes.unset": "未設定",
  "settings.contestPick.entryAxes.hint": "你的 Cabrillo 日誌對參賽組別宣告的其餘內容。Sweepstakes 還會把它作為優先順序字母在空中傳送，因此在你為每一項都選定之前不會開始：ARRL 將 5 瓦及以下計為 QRP、100 瓦及以下計為低功率、超過則計為高功率；使用臺站報告、skimmer 或叢集的參賽組別為Single Operator Unlimited。",
