  "settings.contestPick.entryClass.label": "參賽等級",
  "settings.contestPick.entryClass.hint": "主辦方按本競賽自身規則為你評比的等級，寫入 Cabrillo 日誌的 ENTRY-CLASS 行。在伊利諾伊 QSO 聚會中，同時使用多部發射機的俱樂部參加 UNLIMITED，高功率與低功率等級以 100 瓦 PEP 為界。要證明 QRP 參賽，請在功率類別中選擇 QRP。",
  "settings.contestPick.club.label": "俱樂部",
  "settings.contestPick.club.hint": "你的競賽俱樂部，用於競賽規則含該行的 Cabrillo 日誌 CLUB 行（CQ 系列、伊利諾伊 QSO 聚會）。請按 CQ 要求寫出俱樂部全名。留空則省略該行。",
  "settings.contestPick.operators.label": "其他操作員",
  "settings.contestPick.operators.hint": "Cabrillo 日誌的 OPERATORS 行會列出記錄聯絡時被設為「操作員」的所有人。此處可補充其他人，呼號之間用空格或逗號分隔。",
  "settings.contestPick.transmitter.label": "多人類別",
  "settings.contestPick.transmitter.aria": "你參加的多人類別",
  "settings.contestPick.transmitter.hint": "你的多人參賽同時在空中的訊號數，按本競賽主辦方評比的類別：ONE 為同時一個（多人單機、多人單發射機），TWO 為多人雙機，UNLIMITED 為多人多機，LIMITED 為 ARRL VHF 競賽的受限多人。它寫入 Cabrillo 日誌的 CATEGORY-TRANSMITTER 行，同時附上主辦方要求多人參賽提供的 OPERATORS 行。Nexus 會把所有聯絡標記為發射機 0，因此在提交多人雙機日誌前，請自行補入第二臺發射機的聯絡。",
  "settings.contestPick.overlay.label": "附加類別",
  "settings.contestPick.overlay.aria": "你還參加的附加類別",
