  "settings.rigControl.txAudio.hint": "Nexus 透過 CAT 鍵控時，使用電臺的哪一路音訊輸入發射。<b>前面板/麥克風</b>是 Nexus 一直以來的鍵控方式。<b>後部/資料</b>改為鍵控資料輸入：如果你的音效卡是透過後部 DATA 或 ACC 介面（SignaLink 插的地方）或電臺自帶的 USB 音訊接入電臺，且電臺在 VOX 下有聲、換 Nexus 就沒有聲音，就選它。話音操作臺的 PTT 不受影響，仍按原有方式鍵控電臺。<b>按電臺分別設定。</b>",
