  "settings.rigControl.detect.noModel": "⚠ 找到了連線埠但沒認出確切型號 — 當電臺接在只報自己名字的通用 USB 橋接晶片後面時這很正常（Icom、Yaesu、Kenwood、Elecraft 和 Xiegu 上都很常見）。請在下方 <em>電臺型號</em> 中選擇你的電臺，或點選 <em>自動測試</em>（它會嘗試常見電臺，為你找出正確的連線埠 + 波特率）。",
