  "settings.rigControl.icomLan.hint": "<b>Beta：僅接收與控制。</b>Nexus 不在此連線上發射，也尚不傳輸音訊。電臺側：開啟 Network Control（重啟後生效）和 CI-V Transceive。電臺一次只接受一個網路程式，請先關閉 wfview 或 RS-BA1。僅限 LAN 與 Wi-Fi：從其他網路訪問請用 VPN。",
