  "settings.rigControl.icomLan.port.label": "控制連線埠（UDP）",
  "settings.rigControl.icomLan.port.hint": "預設為 50001，除非你在電臺上改過。",
  "settings.rigControl.icomNative.icomlan": "在 Icom 網路連線下始終開啟：Nexus 正是靠它在電臺上操控電臺。",
  "settings.rigControl.conn.tci": "TCI（SDR 程式）— Beta",
  "settings.rigControl.tci.hint": "<b>Beta。</b>Nexus 連線 SDR 程式自帶的 TCI 伺服器，無需 rigctld，也無需虛擬 COM 口。它讀取並設定頻率與模式，並透過該程式發射。開啟<b>經 TCI 傳輸音訊</b>後，接收音訊與 Nexus 自身的發射音訊也走 TCI。<b>尚未就緒：</b>透過程式自帶鍵控器發 CW（請改用音效卡鍵控器）。請先在程式中開啟 TCI 伺服器。",
  "settings.rigControl.tci.host.label": "SDR 程式地址",
  "settings.rigControl.tci.host.hint": "執行 SDR 程式的電腦：<b>127.0.0.1</b> 表示本機。TCI 無密碼也無加密，因此只能在自己的網路中訪問其他電腦。",
  "settings.rigControl.tci.port.label": "TCI 連線埠",
  "settings.rigControl.tci.port.hint": "程式 TCI 設定中的連線埠：ExpertSDR3 與 Thetis 出廠為 50001，piHPSDR 為 40001。<b>查詢 TCI 伺服器</b>會把兩個都試一遍。",
  "settings.rigControl.tci.find.label": "TCI 伺服器",
