  "settings.rigControl.tci.find.title": "在此地址查詢 SDR 程式的 TCI 伺服器：先試目前連線埠，再試 50001 和 40001。它只讀取伺服器自報的資訊；從不發射，也從不改變電臺。",
  "settings.rigControl.tci.find.searching": "正在 {{host}} 查詢 TCI 伺服器…",
