  "settings.rigControl.tci.find.portSet": "TCI 連線埠現為 {{port}}：儲存後生效。",
  "settings.rigControl.tci.find.nexus": "連線埠 {{port}} 是 Nexus 自己的 TCI 伺服器，不是 SDR 程式。",
