  "settings.q65.submode.e": "E — 16 倍間隔，最耐多普勒",
  "settings.q65.submode.hint": "間隔越寬越能抵抗多普勒展寬與頻率漂移，但犧牲靈敏度。路徑變差時逐級上調 — 高波段 EME 通常需要 B 或 C。",
  "settings.q65.hint": "Q65 可發可收。週期與子模式同時決定你聽到什麼和傳送什麼，且雙方必須一致 — 週期或子模式不同的對方無法解碼你。",
  "settings.phone.legend": "話音（SSB / FM）",
  "settings.phone.mode.title": "模式",
