  "settings.phone.ctcss.label": "CTCSS（PL）亞音",
  "settings.phone.ctcss.off": "關閉",
  "settings.phone.ctcss.hint": "中繼接入亞音（PL）。",
  "settings.phone.mic.title": "麥克風",
  "settings.phone.mic.hint": "麥克風增益與語音鍵控訊息錄製在話音操作臺中（即時 CAT + 一鍵錄製）。",
  "settings.phone.voiceMic.label": "語音麥克風（錄製）",
  "settings.phone.voiceMic.default": "與音訊輸入相同（預設）",
  "settings.phone.voiceMic.hint": "錄製語音鍵控訊息時使用的麥克風。預設從音訊輸入裝置錄製 — 但在數字配置下那是電臺的 RX 音訊，你會錄到波段而不是自己的聲音。請在此選擇你真正的麥克風。若無法開啟，錄製會回退到輸入裝置（絕不會靜默失敗）。",
  "settings.cw.legend": "CW",
  "settings.cw.keyer.title": "鍵控器",
  "settings.cw.keyer.label": "鍵控後端",
  "settings.cw.keyer.cat": "CAT — 由電臺發 CW（Hamlib send_morse；僅較新電臺）",
  "settings.cw.keyer.serial": "串列埠鍵控線（DTR/RTS）— 鍵控電臺的 KEY 插孔",
  "settings.cw.keyer.winkeyer": "WinKeyer — K1EL 硬體鍵控器",
  "settings.cw.keyer.soundcard": "音效卡 — 經資料模式傳送音訊音調（變通方案）",
  "settings.cw.keyer.hint": "Nexus 如何傳送 CW。<b>CAT</b> 使用電臺內部鍵控器，但較老的電臺（如 IC-756PRO III）不支援。<b>串列埠鍵控線</b>把 DTR/RTS 翻轉送入電臺的 KEY 插孔（電臺處於 CW 模式，由電臺整形訊號 — 乾淨的方法，只需一根鍵控線）。<b>WinKeyer</b> 驅動 K1EL 硬體。<b>音效卡</b>鍵控一個音訊音調 — 屬於變通方案；請調整驅動力使 ALC 讀數為零。<b>它會把你的電臺帶離 CW</b>，進入資料模式（DATA-U/DATA-L，好讓音調到達發射機而不是麥克風插孔）；選擇其他任何鍵控器，CW 模式會立刻恢復。也可在 CW 操作臺中即時切換。",
  "settings.cw.keyer.unproven": "CAT CW 鍵控在<b>這部電臺上尚未驗證</b>。其 Hamlib 後端傳送的鍵控命令與其他電臺使用的不同，而無論成敗它都會報成功 — 所以如果沒有發出任何訊號，Nexus 無法告訴你。若 CW 發不出去，請改用串列埠鍵控線、WinKeyer 或音效卡鍵控。",
  "settings.cw.keyer.flexCatStop": "在透過 <b>SmartSDR CAT</b> 連線的 Flex 上，Esc 會立即讓 Nexus 停止，但電臺可能把正在傳送的那個詞發完：SmartSDR CAT 沒有公開的 CW 停止指令，因此 Nexus 一次只交給電臺一個詞。若需要能中途截斷的停止，請在 SmartSDR CAT 的 WinKeyer 連線埠上選擇 <b>WinKeyer</b> 鍵控器，或使用 <b>Flex 原生使用者端</b>。",
  "settings.cw.pitch.label": "側音音高（Hz）",
  "settings.cw.pitch.hint": "CW 音調音高（300–1200 Hz）— 影響音效卡鍵控音調與 CW 頻譜中的零拍標記。",
  "settings.cw.reverse.label": "反向 CW（CW-R）",
  "settings.cw.reverse.aria": "在所有波段使用反向 CW",
  "settings.cw.reverse.hint": "把電臺置於<b>反向</b> CW 模式（CW-R / CW-L），而不是常規 CW，且在<b>所有波段</b>。預設關閉，因此 Nexus 請求的是普通 CW，你的電臺保持其選單設定的狀態。這只改變你聽到某個訊號時的音高 — CW 與 CW-R 的發射完全相同，與你通聯的臺站察覺不到 — 所以這是個人偏好，不是波段規則。實際選中哪個邊帶取決於電臺：Yaesu 上是 CW-L，而 Icom 上則跟隨該機自身的 <b>CW Normal Side</b> 選單。音效卡鍵控器忽略此項，因為它根本不把電臺切到 CW。",
  "settings.cw.winkeyerPort.label": "WinKeyer 連線埠",
  "settings.cw.winkeyerPort.placeholder": "K1EL WinKeyer 串列埠",
  "settings.cw.winkeyerPort.hint": "你的 WinKey 呈現的串列埠。1200 波特。多功能介面（Timewave Navigator、microHAM）內建的 WinKey 晶片也算 — 請使用該裝置的 CW/WinKey 連線埠，而不是它的 CAT 連線埠。",
  "settings.cw.keyPort.label": "鍵控線串列埠",
  "settings.cw.keyPort.placeholder": "鍵控介面（與 CAT 分開）",
  "settings.cw.keyPort.hint": "接入你鍵控介面（Buxcomm、自制 DTR 線等）的 USB 轉串列埠，該介面插在電臺的 KEY 插孔上。必須是與 CAT 分開的連線埠。請把電臺設為 CW 模式，並把其鍵控插孔設為直鍵/臭蟲鍵。內建 WinKey 晶片的介面 — Timewave Navigator、microHAM、K1EL WinKeyer — <b>不會</b>用 DTR 鍵控：請改選上方的 WinKeyer 後端，並給它該裝置的 CW 連線埠。",
  "settings.cw.keyLine.label": "鍵控線",
  "settings.cw.keyLine.dtr": "DTR（CW 慣例）",
  "settings.cw.keyLine.hint": "哪條控制線鍵控電臺。DTR 是標準（RTS = PTT）；若你的介面是反接的，改用 RTS。",
  "settings.cw.idAfter73.label": "73 之後的 CW 標識",
  "settings.cw.idAfter73.hint": "在最後的 73 完全離開空中之後，用 CW 拍發你的呼號，適用於 Q65、FST4 和 MSK144（WSJT-X 原始選項，預設關閉）。與 WSJT-X 一致，FT8 和 FT4 不傳送 CW 標識，FT2、TempoFast 和 TempoDeep 也不發。使用常規 CW 鍵控路徑 — PTT + 音調 — 在發射之後，絕不疊在其上。",
  "settings.cw.macros.title": "宏（F 鍵配置）",
  "settings.cw.macros.label": "CW 操作臺 F 鍵",
  "settings.cw.macros.profiles.aria": "目前 CW 宏配置",
  "settings.cw.macros.profiles.unnamed": "配置 {{n}}",
  "settings.cw.macros.profiles.add": "新建",
  "settings.cw.macros.profiles.addPrompt": "新 CW 宏配置名稱：",
  "settings.cw.macros.profiles.rename": "重新命名",
  "settings.cw.macros.profiles.renamePrompt": "重新命名 CW 宏配置：",
  "settings.cw.macros.profiles.delete": "刪除",
  "settings.cw.macros.profiles.deleteTitle": "刪除此配置",
  "settings.cw.macros.profiles.keepOne": "至少保留一個配置",
  "settings.cw.macros.builtin.hint": "正在使用內建的 F1–F8 組合。自訂可讓它們成為你自己的（標籤 + 模板；權杖：{MYCALL} {RST} {NAME}，以及 ! = 對方呼號）。",
  "settings.cw.macros.customize": "自訂",
  "settings.cw.macros.row.label.aria": "{{key}} 標籤",
  "settings.cw.macros.row.text.aria": "{{key}} 文字",
  "settings.cw.macros.tokens.hint": "權杖：{MYCALL} {NAME} {MYGRID} {MYSTATE} {RST} · ! = 對方呼號 · {HISNAME} {HISSTATE} = 對方在 QRZ 上的姓名/州（{MYSTATE} 需在「設定 ▸ 臺站」中填寫；其餘由副駕/名單點選 + QRZ 查詢自動填充）。每個鍵都保留其角色 — 引導式副駕的下一步高亮跟隨角色，因此自訂文字仍會像以前一樣按 F1→F2→F3→F4 推進。請在你希望插入對方呼號的位置保留 ! 權杖。儲存後生效。",
  "settings.cw.macros.reset": "恢復預設",
