  "settings.cw.macros.role.askRepeat": "請求重發",
  "settings.cw.macros.role.query": "詢問",
  "settings.rtty.legend": "RTTY",
  "settings.rtty.rxAutoArm.label": "開啟 RTTY 時開始接收",
  "settings.rtty.rxAutoArm.hint": "RTTY 介面一開啟就啟動解碼器 — 調到某個訊號上文字就會列印，無需設定。關閉此項則需手動啟用接收（解碼文字窗格中的「啟用接收」按鈕）。這只會啟用接收機 — 發射絕不會替你啟用。",
  "settings.rtty.keying.title": "鍵控",
  "settings.rtty.backend.label": "鍵控後端",
  "settings.rtty.backend.afsk": "AFSK — 音效卡音調經電臺以 LSB 傳送（預設）",
  "settings.rtty.backend.fsk": "真 FSK — 串列埠鍵控線（DTR/RTS），電臺處於 RTTY 模式",
  "settings.rtty.backend.hint": "Nexus 如何傳送 RTTY。<b>AFSK</b> 透過與 FT8 相同的發射音訊通路播放雙音波形（由音效卡定時 = 無抖動；請調整驅動力使 ALC 剛好讀到零）。<b>真 FSK</b> 透過一條串列埠控制線按位翻轉電臺的 FSK 輸入、電臺處於 RTTY 模式 — 從而解鎖其窄帶 RTTY 濾波器（例如 FTDX10 的）— PTT 走 CAT 或它自己的線。軟體 FSK 的時序只到休閒/Field Day 水平；AFSK 是時序最乾淨的路徑。",
  "settings.rtty.afskSideband.label": "AFSK 邊帶",
  "settings.rtty.afskSideband.lsb": "LSB（標準）",
  "settings.rtty.afskSideband.hint": "電臺跑 AFSK 所用的邊帶。LSB 是 RTTY 慣例。在 USB 下，Nexus 會把電臺置入其上部資料模式（DATA-U / USB-D / DIGU）並自行交換音調，這樣 mark 在空中仍是高音，解碼器照樣能抄收 — 請保持「反向」關閉。",
  "settings.rtty.fskPort.label": "FSK 串列埠",
  "settings.rtty.fskPort.placeholder": "例如 FTDX10 的 USB Enhanced COM",
  "settings.rtty.fskPort.hint": "其控制線饋送電臺 FSK 輸入的連線埠。留空 = 使用 CAT 串列埠。",
  "settings.rtty.fskLine.label": "FSK 資料線",
  "settings.rtty.fskLine.dtr": "DTR（常見接法 — RTS 留給 PTT）",
  "settings.rtty.fskLine.hint": "哪條控制線承載資料位。PTT 必須走它自己獨立的通路 — CAT PTT 或獨立的 PTT 線，絕不能用這條；若兩者衝突，Nexus 會拒絕傳送。",
  "settings.rtty.signal.title": "訊號",
  "settings.rtty.baud.label": "波特率",
  "settings.rtty.baud.hf": "45.45 — HF 標準",
  "settings.rtty.baud.vhf": "75 — VHF / 部分網路",
  "settings.rtty.baud.hint": "同時驅動發射位時鐘與接收解調器（真 45.45，絕不取整為 45）。",
  "settings.rtty.shift.label": "頻移（Hz）",
  "settings.rtty.shift.hf": "170 — HF 標準",
  "settings.rtty.shift.hint": "mark/space 間距 — 同時用於發射音調對與接收解調器。",
  "settings.rtty.reverse.label": "反向（交換 mark/space）",
  "settings.rtty.reverse.hint": "在發射和接收解碼器中交換 mark 與 space，用於與顛倒發射的臺站通聯。不要用它來跑 USB：請改選 AFSK 邊帶，它會自行保持正確的極性。",
  "settings.rtty.autoCall.title": "自動呼叫",
  "settings.rtty.autoListen.label": "重發前先聽",
  "settings.rtty.autoListen.hint": "自動呼叫在再次呼叫 CQ 之前等待多久（秒）— 以及向某臺請求重發前的相同等待。計時從你本次發射完全結束開始，而不是從排隊時開始。<b>30 秒</b>是自動呼叫一直以來的做法；只有在你想讓節奏更快或更慢時才改。低於 5 秒會在你剛剛請求的答覆上直接鍵控，因此下限是 5。",
  "settings.rtty.autoRepeats.label": "放棄前的重試次數",
  "settings.rtty.autoRepeats.hint": "自動呼叫在一次聯絡中向某臺再請求多少次後才放手。<b>這不會限制 CQ。</b>無人應答的 CQ 會一直重複直到你停止 — 這正是「停止」按鈕和 TX 開關的用途。",
  "settings.psk.legend": "PSK",
  "settings.psk.rxAutoArm.label": "開啟 PSK 時開始接收",
  "settings.psk.rxAutoArm.hint": "PSK 介面一開啟就啟動解碼器 — 在瀑布圖上點選一條跡線，文字就會列印，無需設定。關閉此項則需手動啟用接收（解碼文字窗格中的「啟用接收」按鈕）。你自己停止接收機的狀態會在本次工作階段內記住。這只會啟用接收機 — 發射絕不會替你啟用。",
  "settings.jtty.title": "JTTY",
  "settings.jtty.rxAutoArm.label": "開啟 JTTY 時開始接收",
  "settings.jtty.rxAutoArm.hint": "JTTY 介面一開啟就啟動其解碼器。關閉此項則需手動啟用接收（「全部解碼」窗格中的「啟用接收」按鈕）。你自己停止接收機的狀態會在本次工作階段內記住。這只會啟用接收機 — 發射絕不會替你啟用。",
  "settings.js8.legend": "JS8",
  "settings.js8.receiving.title": "速度與接收",
  "settings.js8.speed.label": "發射速度",
  "settings.js8.speed.hint": "你的幀以何種速度傳送，以及 TX 時鐘跟隨的週期：Slow 30 秒、Normal 15 秒、Fast 10 秒、JS8 40 6 秒、JS8 60 4 秒。波段上大多用 Normal。JS8 40（JS8Call 3.0 之前稱為 Turbo）和 JS8 60 用於強訊號；JS8Call 3.0 將 JS8 60 標為實驗性。JS8 頂欄的速度膠囊改動的是同一個設定。",
  "settings.js8.rxSpeeds.label": "解碼這些速度",
  "settings.js8.rxSpeeds.hint": "預設同時解碼所有速度，與 JS8Call 一致 — 同一波段上的 Slow 臺站和 JS8 60 臺站都會列印出來。取消勾選某個速度可在小機器上節省 CPU；每條活動行都標有其速度字母（E/A/B/C/I）。在 JS8 60 出現之前儲存的清單會保留原有四個速度：勾選 JS8 60 即可加入。",
  "settings.js8.callsignAgingMin.label": "呼號老化（分鐘）",
  "settings.js8.callsignAgingMin.hint": "預設關閉（0），與 JS8Call 一致。否則，若某臺站已有這麼多分鐘未被聽到，就會從臺站清單中移除，除非你選中了它或它有給你的未讀訊息，且你的 HEARING? 回覆也會排除它。最大 1440（一天）。",
  "settings.js8.activityAgingMin.label": "波段活動老化（分鐘）",
  "settings.js8.activityAgingMin.hint": "預設 2，與 JS8Call 一致。若「波段活動」窗格中某行的最新解碼已過這麼多分鐘，該行會離開窗格，除非 RX 正落在它的偏移上。0 表示保留所有行。最大 1440（一天）。",
  "settings.js8.freq.title": "頻率",
  "settings.js8.returnToLastDial.label": "回到上次使用的頻率",
  "settings.js8.returnToLastDial.hint": "預設關閉，與 JS8Call 一致。開啟後，開啟 JS8 會把電臺調回你上次在 JS8 中使用的頻率，而不是該波段的 JS8 頻率。",
  "settings.js8.freqs.label": "JS8 頻率",
  "settings.js8.freqs.hint.stock": "JS8Call 建議的頻率。改動、增加或刪除任一項後，清單就變成你自己的：JS8 中的波段選擇器會顯示它，開啟 JS8 時調諧到該波段上的第一個。",
  "settings.js8.freqs.hint.own": "你自己的清單：JS8 中的波段選擇器會顯示它，開啟 JS8 時調諧到該波段上的第一個。重設可恢復 JS8Call 的建議頻率。",
