  "settings.js8.sound.file.choose.aria": "為「{{event}}」選擇 WAV 檔案",
  "settings.js8.sound.file.reset.label": "恢復內建音調",
  "settings.js8.sound.file.reset.aria": "播放「{{event}}」的內建音調",
  "settings.js8.sound.device.label": "提示音播放裝置",
  "settings.js8.sound.device.hint": "絕不能用你電臺發射所用的裝置：那裡的聲音可能讓 VOX 電臺誤發，所以 Nexus 不會在那裡播放，即使之後把電臺的 TX 音訊裝置改成它也一樣。",
  "settings.js8.sound.device.tx": "{{device}}（電臺 TX 音訊，不用於提示音）",
  "settings.js8.api.title": "JS8Call API",
  "settings.js8.api.hint": "供為本機上的 JS8Call 編寫的程式使用，例如日誌、地圖和訊息工具。它們可以讀取 Nexus 聽到的內容、收件箱和臺站詳情。它們不能發射、調諧或更改任何東西。其他電腦上的程式無法連線。",
  "settings.js8.api.tcp.label": "TCP API",
  "settings.js8.api.tcp.hint": "程式連線到 127.0.0.1 上的下列連線埠。一次一個，與 JS8Call 一致。",
