  "settings.antennaGain.rx.aria": "RX 天線增益（dBi）",
  "settings.antennaGain.hint": "僅供 P.533 鏈路預算使用。0 = 簡單的線天線/垂直天線（各向同性）；三單元八木 ≈ 6–8。誠實的 v1：只是簡單的 dB 平移 — 無方向圖或起飛角建模，快速啟發式會忽略它。",
  "settings.dxkeeper.note": "把每次記錄的 QSO 經其 TCP 網路服務推送到 <b>DXKeeper</b>。請先在 DXKeeper 的 <em>Configuration ▸ Defaults ▸ Network Service</em> 中啟用。",
  "settings.dxkeeper.host.label": "DXKeeper 主機",
  "settings.dxkeeper.host.placeholder": "留空 = 關閉",
  "settings.dxkeeper.host.hint": "通常是 127.0.0.1 — 同一臺電腦。留空則禁用。",
  "settings.dxkeeper.basePort.hint": "DXKeeper 網路服務面板中的 <em>Base Port</em>（預設 52000）。DXKeeper 本身監聽 <b>{{port}}</b> — Nexus 已替你加上 1。",
  "settings.dxkeeper.uploads.label": "讓 DXKeeper 負責上傳",
  "settings.dxkeeper.uploads.hint": "預設關閉：Nexus 已自行上傳到 LoTW / eQSL / ClubLog / QRZ，開啟此項會讓每筆 QSO 上傳兩次。注意：若 DXKeeper 自身 QSL Configuration 標籤頁中勾選了 <em>Auto upload</em>，它會忽略此設定對 Club Log 和 QRZ 的處理 — 請在那裡取消勾選。",
  "settings.n3fjp.legend": "N3FJP 整合（俱樂部主日誌）",
  "settings.n3fjp.note": "你在競賽模式下記錄的每次聯絡，都會在記錄的瞬間送達俱樂部的主 N3FJP 日誌。Nexus 會填好 <b>N3FJP Field Day Contest Log</b> 的表單（呼號、波段、模式、等級和分區），因此 Field Day 期間整個俱樂部的比分即時更新。CQ WPX、CQ WW RTTY 和 ARRL VHF 競賽也會帶上其交換資訊；QSO 派對、Sweepstakes 或 CQ WW CW/SSB 的聯絡會送達 N3FJP 但不帶交換資訊。請在主控電腦上執行 N3FJP；讓 Nexus 指向其 IP + 連線埠（預設 1100）。",
  "settings.n3fjp.host.label": "N3FJP 主機",
  "settings.n3fjp.host.placeholder": "留空 = 關閉",
  "settings.n3fjp.host.hint": "主日誌電腦的 IP 或主機名。留空則禁用。",
  "settings.n3fjp.port.label": "N3FJP 連線埠",
  "settings.n3fjp.port.hint": "N3FJP 的 API TCP 連線埠（預設 1100）。",
  "settings.n3fjp.useEnter.label": "競賽計分使用 ENTER",
  "settings.n3fjp.useEnter.hint": "用 N3FJP 的 <b>ENTER</b> 序列記錄每次競賽聯絡，它會為競賽計分 — 這是正確的路徑。關閉則回退到普通的 <code>ADDDIRECT</code> 插入（可能不計分）。預設開啟。",
  "settings.n3fjp.reportBand.label": "向 N3FJP 報告我的波段",
  "settings.n3fjp.reportBand.hint": "告訴 N3FJP 你在哪個波段（無需 CAT），這樣俱樂部的網路狀態顯示波段板會顯示此位置。預設關閉。",
  "settings.n3fjp.forwardAll.label": "轉發每筆 QSO",
  "settings.n3fjp.forwardAll.hint": "同時把<b>每個</b>已記錄的 QSO（不只是競賽聯絡）推送到上方主機的 N3FJP ACLog — 用於日常通用日誌。N3FJP 會去重，因此與競賽推送並行是安全的。",
  "settings.n3fjp.test.label": "連線測試",
  "settings.n3fjp.test.title": "儲存設定，然後測試 N3FJP 的 TCP 連線",
  "settings.n3fjp.test.action": "測試 N3FJP",
  "settings.n3fjp.test.hint": "請在活動開始前到俱樂部現場執行一次，確認 API 鏈路可用。",
  "settings.n1mm.legend": "N1MM+ 整合",
  "settings.n1mm.addr.label": "N1MM 聯絡廣播地址",
  "settings.n1mm.addr.placeholder": "留空 = 關閉",
  "settings.n1mm.addr.hint": "N1MM 聯絡資料包發往何處（host:port，UDP）。請寫明連線埠 — 消費者會堆在同一主機上，而 12060 常已被別的日誌程式佔用。留空則禁用。",
  "settings.n1mm.addr.sending": "正在為每個已記錄的 QSO 傳送。",
  "settings.n1mm.addr.idle": "僅填地址只傳送你在競賽模式下記錄的聯絡 — 日常日誌請開啟下方的「廣播每筆 QSO」。",
  "settings.n1mm.broadcastAll.label": "廣播每筆 QSO",
  "settings.n1mm.broadcastAll.hint": "為<b>每個</b>已記錄的 QSO 傳送聯絡資料包，而不只是競賽聯絡 — 把 GridTracker 之類的地圖程式指向上方地址，你記錄時每次聯絡都會標繪在其地圖上。每筆 QSO 只發一個包：這與競賽廣播不會重複，因此整場競賽開著也安全。預設關閉；關閉時資料包<em>只</em>為你以競賽模式記錄的聯絡發出。",
  "settings.confirmations.legend": "確認",
  "settings.confirmations.credential.set.action": "設定",
  "settings.confirmations.credential.forget.action": "忘記",
  "settings.confirmations.credential.forget.title": "從系統鑰匙串中刪除已儲存的密碼",
  "settings.confirmations.lotw.username.label": "LoTW 使用者名稱",
  "settings.confirmations.lotw.username.placeholder": "你的 LoTW 賬戶登入名",
  "settings.confirmations.lotw.username.hint": "通常是你的呼號，但不總是 — 請使用 LoTW 賬戶登入名。儲存設定後生效。",
  "settings.confirmations.lotw.password.label": "LoTW 密碼",
  "settings.confirmations.lotw.password.placeholder": "LoTW 網站密碼",
  "settings.confirmations.lotw.password.hint": "你的 LoTW <b>網站</b>密碼（不是 TQSL 證書密碼）。儲存在作業系統鑰匙串中，絕不寫入磁碟；點選「設定」後不再顯示。",
  "settings.confirmations.lotw.sync.label": "LoTW 確認",
  "settings.confirmations.lotw.sync.action": "下載確認",
  "settings.confirmations.lotw.sync.busy": "下載中…",
  "settings.confirmations.lotw.sync.hint": "此操作只把確認<b>下載</b>下來。要把你的聯絡<em>傳送到</em> LoTW，請使用日誌中的 <b>Upload to LoTW (N)</b>。它會把新的確認拉入你的日誌，並標記哪些上傳 LoTW 已存檔（因此它們顯示為「等對方操作」，而不是「從未上傳」）。首次拉取會覆蓋你的全部歷史（可能較慢）；之後是增量的。",
  "settings.confirmations.lotw.redownload.action": "重新下載全部",
