  "settings.confirmations.lotw.adifLocation.hint": "如果你把 TQSL 設為<em>「使用 ADIF 檔案中的位置」</em>且不建立具名臺站位置（常出行時很方便），請開啟此項。隨後 Nexus 會把你的呼號 + 網格（STATION_CALLSIGN / MY_GRIDSQUARE）寫入上傳內容並省略 <code>-l</code> 引數，TQSL 便按這些簽名，上方的臺站位置也不再必需。<b>整批都會按你上方目前的網格簽名</b>，所以如果你在多個地點操作，請在移動<em>之前</em>上傳 — 否則較早的聯絡會用新網格簽名。例外是合併進日誌的 VHF 競賽聯絡：它用其交換中發出的網格簽名（漫遊臺當時的網格）。",
  "settings.confirmations.lotw.tqslPath.label": "TQSL 路徑（可選）",
